7 | function usage(): never {
8 |   console.error("usage: npm run cli -- [--json] <diff-file>  (or pipe: git diff | npm run cli -- --json)");
9 |   process.exit(2);
10 | }
11 | 
12 | let input: string;
13 | const args = process.argv.slice(2);
14 | const jsonMode = args.includes("--json");
15 | const arg = args.find((a) => a !== "--json");
16 | if (arg && arg !== "-") {
17 |   try {
18 |     input = readFileSync(arg, "utf8");
19 |   } catch {
20 |     console.error(`cannot read ${arg}`);
21 |     usage();
22 |   }
23 | } else if (!process.stdin.isTTY) {
24 |   input = readFileSync(0, "utf8");
25 | } else {
26 |   usage();
27 | }
28 | 
29 | const diff = parseDiff(input!);
30 | if (diff.files.length === 0) {
31 |   console.error("no diff headers found — expected unified diff (git diff, git show, format-patch)");
32 |   process.exit(2);
33 | }
34 | 
35 | const findings = runRules(diff);
36 | const grade = scoreFindings(findings);
37 | 
38 | if (jsonMode) {
39 |   console.log(
40 |     JSON.stringify(
41 |       {
42 |         grade: grade.grade,
43 |         score: grade.score,
44 |         verdict: grade.verdict,
45 |         counts: grade.counts,
46 |         files: diff.files.map((f) => ({
47 |           path: f.newPath ?? f.oldPath,
48 |           status: f.status,
49 |         })),
50 |         totals: { added: diff.totalAdded, removed: diff.totalRemoved },
51 |         findings,
52 |       },
53 |       null,
54 |       2,
55 |     ),
56 |   );
57 | } else {
58 |   console.log(buildMarkdownReport(diff, findings, grade));
59 | }
60 | 
61 | const EXIT_BY_GRADE: Record<string, number> = { A: 0, B: 0, C: 1, D: 1, F: 1 };
62 | process.exit(EXIT_BY_GRADE[grade.grade]);
