12 | const CODE_EXT = /\.(ts|tsx|js|jsx|mjs|cjs|py|go|rs|java|kt|rb|php|cs|cpp|c|h|hpp|swift|scala|sh|sql)$/i;
13 | const TEST_PATH = /(^|\/)(tests?|__tests__|spec|e2e)(\/|$)|(_test|_spec|\.test|\.spec)\.(ts|tsx|js|jsx|py|go|rs|java|rb|php|cs)$/i;
14 | const LOCKFILE = /(^|\/)(package-lock\.json|yarn\.lock|pnpm-lock\.yaml|poetry\.lock|Pipfile\.lock|go\.sum|Cargo\.lock|Gemfile\.lock|composer\.lock|packages\.lock\.json)$/i;
15 | const MANIFEST = /(^|\/)(package\.json|requirements[^/]*\.txt|pyproject\.toml|setup\.py|setup\.cfg|go\.mod|Cargo\.toml|Gemfile|composer\.json|pom\.xml|build\.gradle(\.kts)?|.*\.csproj|Podfile)$/i;
16 | const MIGRATION_PATH = /migrations?|db\/migrate|alembic|flyway|liquibase|schema\/changes/i;
17 | const ENV_EXAMPLE = /(^|\/)\.env\.(example|sample|template|defaults)$|\.env\.example$|env\.example/i;
18 | const SENSITIVE_PATH = /auth|login|oauth|sso|jwt|session|password|credential|payment|billing|checkout|invoice|stripe|paypal|crypto|encrypt|decrypt|secret|token|permission|rbac|acl|security|csrf|xss|cert|key/i;
