25 | const SECRET_PATTERNS: SecretPattern[] = [
26 |   { name: "AWS access key", re: /\b(AKIA|ASIA|ABIA|ACCA)[0-9A-Z]{16}\b/ },
27 |   { name: "AWS secret key", re: /\baws_secret_access_key\s*[:=]\s*["']?[0-9a-zA-Z/+]{30,}/i },
28 |   { name: "private key block", re: /-----BEGIN [A-Z ]*PRIVATE KEY( BLOCK)?-----/ },
29 |   { name: "GitHub token", re: /\b(ghp_[0-9a-zA-Z]{30,}|github_pat_[0-9a-zA-Z_]{30,}|gho_[0-9a-zA-Z]{30,}|ghs_[0-9a-zA-Z]{30,})\b/ },
