31 |   { name: "Slack token", re: /\bxox[baprs]-[0-9a-zA-Z-]{10,}\b/ },
32 |   { name: "Stripe key", re: /\b(sk_live|pk_live|rk_live)_[0-9a-zA-Z]{16,}\b/ },
33 |   { name: "Google API key", re: /\bAIza[0-9A-Za-z_-]{35}\b/ },
34 |   { name: "generic secret assignment", re: /\b(api[_-]?key|api[_-]?secret|secret[_-]?key|access[_-]?token|auth[_-]?token|client[_-]?secret|private[_-]?key|passwd|password)\b\s*[:=]\s*["'][^"'\s]{8,}["']/i },
