74 | function shannonEntropy(s: string): number {
75 |   if (!s.length) return 0;
76 |   const freq = new Map<string, number>();
77 |   for (const ch of s) freq.set(ch, (freq.get(ch) ?? 0) + 1);
78 |   let e = 0;
79 |   for (const c of freq.values()) {
80 |     const p = c / s.length;
81 |     e -= p * Math.log2(p);
82 |   }
83 |   return e;
84 | }
