379 |         const codeLines: Array<{ no: number | undefined; text: string }> = [];
380 |         for (const l of addedLines(f)) {
381 |           const prefixMatch = COMMENTED_CODE_PREFIX.exec(l.text);
382 |           if (!prefixMatch) continue;
