411 | export interface RuleInfo {
412 |   id: string;
413 |   name: string;
414 |   severity: Severity;
415 |   description: string;
416 | }
417 | 
418 | export function listRules(): RuleInfo[] {
419 |   return rules.map((r) => ({ id: r.id, name: r.name, severity: r.severity, description: r.description }));
420 | }
421 | 
422 | export function runRules(diff: ParsedDiff): Finding[] {
423 |   const out: Finding[] = [];
424 |   for (const r of rules) out.push(...r.run.call(r, diff));
425 |   const order: Severity[] = ["critical", "high", "medium", "low", "info"];
426 |   out.sort((a, b) => order.indexOf(a.severity) - order.indexOf(b.severity));
427 |   return out;
428 | }
